/**
 * Billing-period calendar arithmetic and the charge formulas built on it.
 * Pure functions: the renewal job and `BillingService` share them so a period
 * boundary or a prorated amount can never disagree between the two.
 */
import { getPlanLimits } from "@/config/plan-limits";
import { toIsoTimestamp } from "@/types/common";
import type { BillingInterval, PlanId } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Months one period of `interval` spans. */
export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * The end of a period starting at `start`: the same day `months` later at the
 * same UTC time of day, clamped to the target month's last day when it has no
 * such day (31 January + 1 month → 28 February).
 */
export function addMonthsClamped(start: Date, months: number): Date {
  const year = start.getUTCFullYear();
  const month = start.getUTCMonth() + months;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  const day = Math.min(start.getUTCDate(), lastDay);

  return new Date(
    Date.UTC(
      year,
      month,
      day,
      start.getUTCHours(),
      start.getUTCMinutes(),
      start.getUTCSeconds(),
      start.getUTCMilliseconds(),
    ),
  );
}

export function periodEndFor(
  start: IsoTimestamp | Date,
  interval: BillingInterval,
): IsoTimestamp {
  const from = typeof start === "string" ? new Date(start) : start;
  return toIsoTimestamp(addMonthsClamped(from, monthsInInterval(interval)));
}

/** Full charge for one period: price per seat × seats × months, in cents. */
export function fullPeriodCharge(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
    getPlanLimits(plan).priceCentsPerSeatMonthly *
    seats *
    monthsInInterval(interval)
  );
}

/**
 * Scales a full-period amount to what is left of the period at `now`: started
 * days left over whole days in the period, rounded down to whole cents.
 */
export function prorate(
  fullAmountCents: number,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
  now: Date,
): number {
  if (fullAmountCents <= 0) return 0;

  const start = new Date(periodStart).getTime();
  const end = new Date(periodEnd).getTime();
  const msLeft = end - now.getTime();
  if (msLeft <= 0) return 0;

  const daysInPeriod = Math.max(1, Math.round((end - start) / MS_PER_DAY));
  const daysLeft = Math.min(Math.ceil(msLeft / MS_PER_DAY), daysInPeriod);

  return Math.floor((fullAmountCents * daysLeft) / daysInPeriod);
}

