/**
 * Rolls subscriptions whose period ended onto the next one, invoicing every paid period, and lets due cancellations take effect.
 *
 * Must call (do not reimplement): emit, issueInvoice, isArchived
 */
import { fullPeriodCharge, periodEndFor } from "@/lib/billing-period";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import { isArchived } from "@/lib/soft-delete";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { issueInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** Where a cancelled subscription lands once its cancellation date passes. */
const FALLBACK_PLAN = "free" as const;

const logger = createLogger("billing-renewal-job");

/**
 * One sweep over every live workspace. Replay-safe by construction: once a
 * subscription has been rolled forward its period end lies after `now`, and a
 * cancellation that took effect leaves an active free subscription behind, so
 * a second run at the same instant finds nothing to do.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listAllSubscriptions();

    for (const subscription of subscriptions) {
      const orgId = subscription.orgId as OrgId;

      try {
        const org = await orgRepo.findOrgById(orgId);
        if (!org || isArchived(org)) continue;

        if (subscription.status === "canceled") {
          if (await endCancellation(subscription, now)) result.processed += 1;
          continue;
        }

        if (subscription.status === "active") {
          if (await renew(subscription, now)) result.processed += 1;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/**
 * Adds one period per elapsed interval until the period end lies after `now`,
 * invoicing each new paid period at the current seat count.
 */
async function renew(subscription: Subscription, now: Date): Promise<boolean> {
  const orgId = subscription.orgId as OrgId;
  let periodEnd = subscription.currentPeriodEnd;
  let renewed = false;

  while (new Date(periodEnd).getTime() <= now.getTime()) {
    const nextStart = periodEnd;
    const nextEnd = periodEndFor(nextStart, subscription.interval);
    const amountCents = fullPeriodCharge(
      subscription.plan,
      subscription.seats,
      subscription.interval,
    );

    // A run that died between invoicing and moving the period must not bill
    // the same period twice when it is retried.
    const needsInvoice =
      amountCents > 0 &&
      (await invoiceRepo.findInvoiceForPeriod(orgId, nextStart, nextEnd)) ===
        null;

    await subscriptionRepo.updateSubscriptionPeriod(orgId, nextStart, nextEnd);

    if (needsInvoice) {
      await issueInvoice(orgId, {
        amountCents,
        periodStart: nextStart,
        periodEnd: nextEnd,
        actorId: null,
        occurredAt: toIsoTimestamp(now),
      });
    }

    periodEnd = nextEnd;
    renewed = true;
  }

  return renewed;
}

/**
 * A due cancellation drops the workspace to the free plan as of the
 * cancellation date, on a fresh monthly period starting there.
 */
async function endCancellation(
  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  if (subscription.cancelAt === null) return false;
  if (new Date(subscription.cancelAt).getTime() > now.getTime()) return false;

  const orgId = subscription.orgId as OrgId;
  const periodStart = toIsoTimestamp(subscription.cancelAt);

  const downgraded = await subscriptionRepo.replaceSubscriptionTerms(orgId, {
    plan: FALLBACK_PLAN,
    interval: "monthly",
    status: "active",
    cancelAt: null,
    currentPeriodStart: periodStart,
    currentPeriodEnd: periodEndFor(periodStart, "monthly"),
  });

  await emit("billing.plan_changed", {
    orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(now),
    from: subscription.plan,
    to: FALLBACK_PLAN,
  });

  // A cancellation long past leaves free periods to catch up on as well.
  await renew(downgraded, now);
  return true;
}

