 * subscription has been rolled forward its period end lies after `now`, and a
 * cancellation that took effect leaves an active free subscription behind, so
 * a second run at the same instant finds nothing to do.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listAllSubscriptions();

    for (const subscription of subscriptions) {
      const orgId = subscription.orgId as OrgId;

      try {
        const org = await orgRepo.findOrgById(orgId);
        if (!org || isArchived(org)) continue;

        if (subscription.status === "canceled") {
          if (await endCancellation(subscription, now)) result.processed += 1;
          continue;
        }

        if (subscription.status === "active") {
          if (await renew(subscription, now)) result.processed += 1;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

