/**
 * Cron-style trigger for the billing renewal.
 *
 * Owner D. The job decides which subscriptions are due — a period that ended,
 * a cancellation whose date arrived — so calling this every hour is correct
 * and calling it twice at the same instant is harmless.
 *
 * Must call (do not reimplement): runBillingRenewalJob
 */

import { assertCronSecret, errorResponse } from "@/app/api/_lib/responses";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";

export const dynamic = "force-dynamic";

export async function POST(request: Request): Promise<Response> {
  try {
    assertCronSecret(request);

    const result = await runBillingRenewalJob(new Date());
    return Response.json(result);
  } catch (error) {
    return errorResponse(error);
  }
}

