import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as billingService from "@/server/services/billing-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";
import { getDb, subscriptions, activityEvents } from "@/server/db";
import { eq } from "drizzle-orm";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

it("dates", () => {
  expect(addMonthsClamped(new Date("2026-01-31T10:00:00Z"), 1).toISOString()).toBe("2026-02-28T10:00:00.000Z");
  expect(addMonthsClamped(new Date("2028-02-29T10:00:00Z"), 12).toISOString()).toBe("2029-02-28T10:00:00.000Z");
  expect(prorate(3000, "2026-01-01T00:00:00.000Z" as never, "2026-01-31T00:00:00.000Z" as never, new Date("2026-01-16T02:00:00Z"))).toBe(1500);
});

