  const now = new Date("2026-04-15T00:00:00Z");
  await runBillingRenewalJob(now);
  await runBillingRenewalJob(now);
  const sub = await subscriptionRepo.findSubscription(t.org.id);
  console.log(sub, await invoiceRepo.listInvoices(t.org.id));
  expect(events.length).toBe(3);
  const notes = await notificationRepo.listNotifications({ orgId: t.org.id, recipientId: t.userIds.owner, unreadOnly: false, limit: 50, cursor: null } as never);
  console.log(notes.items.map((n) => n.kind));
  console.log(getDb().select().from(activityEvents).all().map((a) => a.action));
  await billingService.updateSeats(t.actors.owner, { orgId: t.org.id, seats: 4 });
  console.log(await invoiceRepo.listInvoices(t.org.id));
  await billingService.cancelSubscription(t.actors.owner, { orgId: t.org.id, cancelImmediately: true });
  await runBillingRenewalJob(new Date(Date.now() + 1000));
  console.log(await subscriptionRepo.findSubscription(t.org.id));
});
EOF
